"""Countability transfer between two enumerated systems, demonstrated on the
primes (system A) and the squares (system B)."""
from __future__ import annotations
from typing import Callable, List


def nth_prime(k: int) -> int:
    """Return the k-th prime (0-indexed): the enumeration A -> N inverse."""
    primes: List[int] = []
    cand = 2
    while len(primes) <= k:
        if all(cand % p for p in primes if p * p <= cand):
            primes.append(cand)
        cand += 1
    return primes[k]


def prime_index(p: int) -> int:
    """Encode a prime as its position k (system A -> N)."""
    k, cand = 0, 2
    while True:
        is_prime = cand > 1 and all(cand % d for d in range(2, int(cand ** 0.5) + 1))
        if is_prime:
            if cand == p:
                return k
            k += 1
        cand += 1


def square(k: int) -> int:
    """Decode a natural k as the k-th square (N -> system B)."""
    return k * k


def transfer(encode_a: Callable[[int], int], decode_b: Callable[[int], int]) -> Callable[[int], int]:
    """f = decode_b o encode_a, the comparison bijection factoring through N."""
    return lambda a: decode_b(encode_a(a))


def main() -> None:
    f = transfer(prime_index, square)
    print("prime p  ->  index k  ->  square k^2")
    for p in (2, 3, 5, 7, 11, 13):
        print(f"   {p:>3}   ->   {prime_index(p):>3}   ->   {f(p):>4}")


if __name__ == "__main__":
    main()

