function enumerate(num_symbols):
    length <- 0
    loop forever:
        for code in 0 .. num_symbols^length - 1:
            yield base-`num_symbols` digits of `code`, padded to `length`
        length <- length + 1

function index(word):
    offset <- (num_symbols^len(word) - 1) / (num_symbols - 1)
    rank   <- fold word as a base-`num_symbols` number
    return offset + rank

